INSERT INTO `web_karir` (`idartikel`, `idkategori`, `judul_artikel`, `slug_artikel`, `ringkasan_artikel`, `konten`, `tgl_input`, `tgl_update`, `tgl_publish`, `status_artikel`, `meta_keyword`, `meta_description`, `header_konten`, `created_by`, `utc_offset`) VALUES
(14, 1, ' Job Vacancy: Web Application Developer at PMPLand !', NULL, NULL, '<p><span style=\"font-size:0.875rem;\">🚀</span><span style=\"font-size:0.875rem;\"> Job Vacancy - HeadOffice</span><span style=\"font-size:0.875rem;\">🚀</span></p><br /><p class=\"MsoNormal\">Kami sedang mencari Web Application Developer berbakat untuk<br />bergabung dengan tim kami di Cirebon! Jika kamu memiliki passion dalam<br />pengembangan web, ini kesempatanmu!</p><br /><p class=\"MsoNormal\">Jika kamu memiliki antusiasme untuk mengembangkan diri dan<br />siap memberikan kontribusi terbaik. mari bertumbuh dan berinovasi bersama! <span>🌱</span></p><p class=\"MsoNormal\"><span>📌</span> Kirim CV dan portofolio<br />kamu ke karir@pmpland.co.id </p><br /><p class=\"MsoNormal\">Tuliskan kode posisi di subjek email: Web Application<br />Developer</p><br /><p class=\"MsoNormal\">Ayo bergabung dengan PMPland dan tumbuh bersama kami!</p>', '2025-04-28 13:47:21', '2025-07-14 15:42:45', '2025-04-28 13:47:21', 2, 'pmpland,loker,lokercirebon,cirebon,jawabarat,programmer,web,web application developer', 'PMPLand membuka peluang kerja untuk Web Application Developer', 'https://pmpland.co.id/sub-www/images/logo/PMPLand-GROUPLOGO-WHITE-FINAL.png', 'Darrian Jovan', '+07:00'),
(15, 1, 'Job Vacancy : Staff Finance at Head Office PMPLand!', NULL, NULL, '<p>✨ JADILAH BAGIAN DARI TIM KAMI! ✨</p><p><br /></p><p>Apakah Anda seorang profesional keuangan yang mencari tantangan baru? PMPLand membuka kesempatan untuk Anda bergabung sebagai STAFF FINANCE!</p><p><br /></p><p>🚀 Kami mencari individu berbakat yang siap:</p><p>-Mengembangkan karir di industri keuangan yang dinamis</p><p>-Menerapkan keahlian akuntansi dalam lingkungan kerja kolaboratif</p><p>-Menjadi bagian penting dari pertumbuhan perusahaan kami</p><p><br /></p><p>🌟 Bagi Anda yang:</p><p>-Memiliki latar belakang S1 Akuntansi</p><p>-Bersemangat menganalisis angka &amp; membuat laporan yang akurat</p><p>-Ingin bekerja di perusahaan yang menghargai ketelitian &amp; integritas</p><p>-Siap berkontribusi dalam tim yang supportif</p><p><br /></p><p>Inilah saatnya untuk hashtag#RiseToServe bersama PMPLand!</p><p><br /></p><p>💌 Langkah mudah untuk bergabung: </p><p>Kirimkan CV terbaikmu ke karir@pmpland.co.id Subject: Staff Finance</p><p><br /></p><p>Kesempatan tidak datang dua kali. Ayo bergabung dengan keluarga PMPLand dan wujudkan potensimu!</p>', '2025-07-04 08:37:46', '2025-09-03 16:18:51', '2025-07-04 08:37:46', 2, 'Staff,Finance,PMPLand,Property,Loker,Lowongan Kerja,Head Office,Kerja', 'Lowongan Kerja Staff Finance di PMPLand', 'https://app.pmpland.co.id/file-sharing-5175ba066c415db3e8188861a3910faa/HR/Karir//PMPLAND-JOB%20VACANCY-STAFF%20FINANCE-01.png', 'Darrian Jovan', '+07:00'),
(16, 1, 'Job Vacancy : Staff Admin Social Media at Head Office PMPLand!', NULL, NULL, '<p class=\"whitespace-normal break-words\">🚀 We Are Hiring! Join Our Creative Family! 🚀</p><p class=\"whitespace-normal break-words\">Hai, Sobat Kreatif! 👋</p><p class=\"whitespace-normal break-words\">PMPland lagi cari teman baru nih untuk gabung jadi Admin Media Sosial. Kalau kamu suka main sosmed, punya ide-ide segar, dan pengen kerja di lingkungan yang fun &amp; supportive, ini kesempatan kamu!</p><p class=\"whitespace-normal break-words\"><br /></p><p class=\"whitespace-normal break-words\">Yang kami cari: ✨ Jago bikin konten yang bikin orang scroll berhenti 📱 Update sama trend sosmed terkini 🎨 Punya skill desain &amp; video editing 💡 Kreatif dan inovatif 🗣️ Komunikatif dan ramah</p><p class=\"whitespace-normal break-words\"><br /></p><p class=\"whitespace-normal break-words\">Tugas seru yang bakal kamu jalani:</p><ul><li>-Bikin strategi sosmed yang kece</li><li class=\"whitespace-normal break-words\">-Ngobrol sama followers (yes, dibayar buat main sosmed!)</li><li class=\"whitespace-normal break-words\">-Analisis performa konten</li><li class=\"whitespace-normal break-words\">-Jaga image online perusahaan tetap ciamik</li></ul><p class=\"whitespace-normal break-words\"><br /></p><p class=\"whitespace-normal break-words\">Syaratnya gampang kok:</p><ul class=\"[&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc space-y-1.5 pl-7\"><li class=\"whitespace-normal break-words\">-Minimal D3 (Komunikasi/sejenis lebih oke)</li><li class=\"whitespace-normal break-words\">-Pengalaman 1 tahun menjadi admin sosmed</li><li class=\"whitespace-normal break-words\">-Menguasai berbagai platform sosmed</li><li class=\"whitespace-normal break-words\">-Bisa pakai aplikasi desain &amp; editing</li></ul><p class=\"whitespace-normal break-words\"><br /></p><p class=\"whitespace-normal break-words\">📍 Lokasi: Cirebon, Jawa Barat</p><p class=\"whitespace-normal break-words\"><br /></p><p class=\"whitespace-normal break-words\">Tertarik? Langsung kirim CV dan portfolio kamu ke: 📧 <a href=\"mailto:karir@pmpland.co.id\">karir@pmpland.co.id</a> Subject: Admin Medsos</p><p class=\"whitespace-normal break-words\"><br /></p><p class=\"whitespace-normal break-words\">Yuk, jadi bagian dari keluarga PMPland! Kita tunggu ya aplikasimu! 🎉</p><p class=\"whitespace-normal break-words\">#Hiring #LokerCirebon #SocialMediaAdmin #PMPland #KarirDigital #LokerMediaSosial #JobVacancy #RiseToServe</p>', '2025-07-14 15:58:17', '2025-09-03 16:19:07', '2025-07-14 15:58:17', 2, 'Hiring,Loker,Lowongan Kerja,Cirebon,Social Media,Social Media Admin,Karir,Job,PMPLand,RiseToServe', 'Lowongan kerja Admin Media Sosial di PMPland Cirebon. Minimal D3, pengalaman 1 tahun. Kirim CV ke karir@pmpland.co.id. Bergabunglah dengan tim kreatif kami', 'https://app.pmpland.co.id/file-sharing-5175ba066c415db3e8188861a3910faa/HR/Karir//PMPLAND-JOB%20VACANCY-ADMIN%20MEDSOS-CAROUSEL-01.png', 'Darrian Jovan', '+07:00'),
(17, 1, 'Job Vacancy: Web Application Developer at PMPLand 2 !', NULL, NULL, '<p>Test</p>', '2025-10-29 17:11:07', NULL, '0000-00-00 00:00:00', 2, 'pmpland,loker,lokercirebon,cirebon,jawabarat,programmer,web,web application developer', 'PMPLand membuka peluang kerja untuk Web Application Developer', 'https://pmpland.co.id/sub-www/images/logo/PMPLand-GROUPLOGO-WHITE-FINAL.png', 'Edwi Muhaimin Yusuf', '+07:00'),
(18, 1, 'Job Vacancy : Staf Admin Kantor at Bogor!', NULL, NULL, '<p>Halo, Sobat PMPLand! 🚀</p><p><br /></p><p>Kami sedang mencari Admin Kantor yang siap bergabung dengan tim kami di area Bogor-Cibungbulang. Kalau kamu detail-oriented, jago kelola dokumen, dan nyaman bekerja dengan sistem digital, ini kesempatan yang tepat!</p><p><br /></p><p>Yang Kami Cari:</p><p>✨ D3 Administrasi/Akuntansi</p><p>✨ Pengalaman min. 1 tahun di bidang administrasi</p><p>✨ Mahir Microsoft Office &amp; Google Workspace</p><p>✨ Teliti, disiplin, dan komunikatif</p><p>✨ Siap handle dokumen fisik &amp; digital</p><p><br /></p><p>Tanggung Jawab:</p><p>📋 Kelola dokumen legal, perizinan, dan keuangan proyek</p><p>💼 Maintain dokumen fisik dan digital</p><p>📊 Support transaksi keuangan dan payment tracking</p><p><br /></p><p>Ready to grow with us? Kirim CV dan portofolio kamu ke:</p><p>📧 <a href=\"http://bit.ly/AdminBogor3\">PMPLand Career</a></p><p><br /></p><p><br /></p><p>Let\'s build something great together! 💼</p><p><br /></p><p>📧 <a href=\"https://www.kitalulus.com/company/pmpland-fcvv?tab=PROFILE\">Lihat Karir PMPLand Lainnya</a></p><p><br /></p><p>#PMPLand #RiseToServe #LokerBogor #AdminKantor #KarirIndonesia #WeAreHiring #JobOpportunity</p>', '2025-10-29 17:11:08', '2026-04-09 02:43:41', '2025-10-29 17:11:08', 2, 'PMPLand,RiseToServe,LokerBogor,Bogor,Cibungbulang,Jabodetabek,Kerja,LowonganKerja,Jakarta', 'Lowongan Staff Administrasi Kantor di PMPLand Bogor Cibungbulang. Min. D3, pengalaman 1 tahun. Kirim CV ke karir@pmpland.co.id. Info lengkap di sini!', 'https://dummyimage.com/600x400/000/fff', 'Darrian Jovan', '+07:00'),
(19, 1, 'Job Vacancy : Digital Marketing Specialist at Raywhite Sentul City', NULL, NULL, '<p>Calling all Digital Marketing Enthusiasts!</p><p><br /></p><p>Siap kasih impact di industri properti? Ray White Sentul City lagi cari Digital Marketing Specialist yang passionate dan punya pengalaman ngeboost kampanye digital!</p><p><br /></p><p>Yang kami cari:</p><p>✨ Minimal D3 dengan pengalaman 1 tahun di digital marketing (properti/e-commerce/otomotif lebih disukai)</p><p>✨ Jagoan content creation &amp; copywriting</p><p>✨ Ahli kelola Digital Ads di berbagai platform</p><p>✨ Paham funnel marketing dari A sampai Z</p><p>✨ Familiar dengan SEO &amp; SEM</p><p><br /></p><p>Your mission:</p><p>Merancang dan mengoptimalkan seluruh aktivitas digital marketing proyek properti kami - dari strategi iklan berbayar, konten digital, sampai analisis performa kampanye untuk mening-katkan leads dan konversi penjualan properti.</p><p><br /></p><p>Why join us?</p><p>Kesempatan berkembang di perusahaan properti terkemuka dengan proyek-proyek menarik dan tim yang solid!</p><p><br /></p><p>Interested?</p><p>📧 Kirim CV dan portofolio ke: sentulcity@raywhite.co.id</p><p>📝 Subject email: DMS</p><p>Ray White Sentul City</p><p><br /></p><p>📍 Ruko Plaza Niaga 2 Blok G-21 Jl. MH. Thamrin, Sentul City Cileungsi, Babakan Madang, Bogor 16810</p><p>Let\'s grow together! 💼</p>', '2025-10-30 08:57:05', '2026-04-09 02:44:44', '2025-10-30 08:57:05', 2, 'Digital Marketing,Lowongan Kerja,Sentul,Raywhite,Specialist,Digital Marketing Specialist,Digital Ads,SEO,SEM,Bogor,Jabodetabek,Meta', 'Buka Lowongan kerja di Sentul City untuk Raywhite sebagai Digital Marketing Specialist.', 'https://dummyimage.com/600x400/000/fff', 'Darrian Jovan', '+07:00'),
(20, 1, 'Job Vacancy : Customer Service & Administration at Raywhite Sentul City', NULL, NULL, '<p>Your Next Career Move Starts Here!</p><p><br /></p><p>Punya skill komunikasi yang oke dan suka bantu orang? Ray White Sentul City lagi butuh Customer Service &amp; Administration yang bisa jadi problem solver andal untuk customer kami!</p><p>Kamu yang kami cari:</p><p><br /></p><p>✨ Wanita, minimal D3</p><p>✨ Punya pengalaman min. 1 tahun di administrasi atau CS</p><p>✨ Jago Excel &amp; MS Word (no worry, ga perlu level advanced kok!)</p><p>✨ Domisili Sentul, Bogor dan sekitarnya</p><p>✨ Fast learner dan ga takut tantangan baru</p><p>✨ Komunikatif, friendly, dan berpenampilan menarik</p><p><br /></p><p>What you\'ll do:</p><p>Jadi front liner yang answer semua pertanyaan tentang properti dan layanan kami - both via telepon atau langsung ketemu customer. Plus, bantuin handle administrasi kantor biar semuanya berjalan smooth!</p><p><br /></p><p>What\'s in it for you?</p><p>Lingkungan kerja yang supportive, kesempatan belajar banyak hal baru di industri properti, dan tentunya career growth yang jelas!</p><p><br /></p><p>Ready to join?</p><p>📧 Email CV kamu ke: sentulcity@raywhite.co.id</p><p>📝 Subject: CS Admin</p><p><br /></p><p>Ray White Sentul City</p><p>📍 Ruko Plaza Niaga 2 Blok G-21 Jl. MH. Thamrin, Sentul City Cileungsi, Babakan Madang, Bogor 16810</p><p>Let\'s make great things happen together! ✨</p>', '2025-10-30 08:59:29', '2025-12-05 17:23:01', '2025-10-30 08:59:29', 2, 'Raywhite,Customer Service,Admin,Jabodetabek,Sentul City,Excel,Bogor', 'Ray White Sentul City lagi butuh Customer Service & Administration yang bisa jadi problem solver andal untuk customer kami!', 'https://app.pmpland.co.id/thumb-251030085719--640x640-bgNoBG-a058832520734a243b05706a06ae9011-WhatsApp-Image-2025-10-29-at-17.03.03.jpeg', 'Darrian Jovan', '+07:00'),
(21, 1, 'Future Leaders Program PMPLand is Here! Come Join Us!', NULL, NULL, '<p>FUTURE LEADERS PROGRAM BATCH 1 IS OPEN! </p><p><br /></p><p>PMPLand Group membuka kesempatan emas bagi para fresh graduate dan young professional untuk bergabung dalam Future Leaders Program - sebuah perjalanan transformatif yang akan membentukmu menjadi pemimpin masa depan.</p><p><br /></p><p>📅 Periode Pendaftaran: 6 - 27 November 2025</p><p>Daftar Sekarang: Bit.ly/FutureLeaderPMP</p><p><br /></p><p>#RiseToServe #FutureLeadersPMPLand #PMPLandCareers #PMPLandGroup #KarirProperti #FreshGraduate #ManagementTrainee</p>', '2025-11-07 11:39:20', '2026-04-09 02:44:18', '2025-11-07 11:39:20', 2, 'Management Trainee,MT,Future Leaders,Leadership,Project Management,Loker,Lowongan Kerja, Fresh Graduate,Karir', 'PMPLand Group membuka kesempatan emas bagi para fresh graduate dan young professional untuk bergabung dalam Future Leaders Program - sebuah perjalanan tran', 'https://dummyimage.com/600x400/000/fff', 'Darrian Jovan', '+07:00'),
(22, 1, ' Job Vacancy: Web Application Developer at PMPLand !', NULL, NULL, '<p>🚀 WE ARE HIRING!</p><p><br /></p><p>PMPLand sedang mencari Web Application Developer berbakat untuk</p><p>bergabung dengan tim kami di Cirebon! </p><p><br /></p><p>Yang Kami Cari :</p><p>✅ Min. S1 IT/SI/Ilmu Komputer<br /></p><p>✅ Pengalaman min. 3 tahun di bidang serupa<br /></p><p>✅ Kuasai PHP OOP, JavaScript, REST API</p><p>✅ Menguasai RDBMS MariaDB/MySQL</p><p>✅ Memiliki insting desain yang lebih baik (point plus) </p><p><span style=\"font-size:0.875rem;\"><br /></span></p><p><span style=\"font-size:0.875rem;\">Jika kamu passionate di dunia web development dan siap berkembang bersama kami, ini saatnya! 💻</span></p><p><br /></p><p>📩 Lamar sekarang: <a href=\"http://bit.ly/LokerITPMPLand\">bit.ly/LokerITPMPLand</a></p><p>📍 Penempatan: Cirebon, Jawa Barat</p><p><br /></p><p>📧<a href=\"http://kitalulus.com/company/pmpland-fcvv?tab=PROFILE\">Lihat Karir PMPLand lainnya</a></p><p><br /></p><p>#PMPLand #RiseToServe #Loker #LokerCirebon #WebDeveloper #ITJobs #KarirIT #LowonganKerja</p>', '2025-11-28 10:03:16', '2025-11-28 11:23:24', '2025-11-28 10:03:16', 1, 'pmpland, loker, lokercirebon, cirebon, jawabarat, programmer, web, web application developer', 'PMPLand membuka peluang kerja untuk Web Application Developer', 'https://app.pmpland.co.id/file-download/sharing/503fbac5980bad52ee34e3bbb256eda6/212a8ac95e5301b5a4286a6d6b775d8f/lokeritpmpland.jpg', 'Ardhia Shafira Gianti', '+07:00'),
(23, 1, 'Job Vacancy: Finance Staff at Head Office PMPLand!', NULL, NULL, '<p class=\"font-claude-response-body whitespace-normal break-words\">📢 WE ARE HIRING!</p><p class=\"font-claude-response-body whitespace-normal break-words\"><br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">Jika Anda seorang profesional keuangan yang sedang mencari tantangan baru, PMPLand membuka kesempatan untuk bergabung sebagai Staff Finance!</p><p class=\"font-claude-response-body whitespace-normal break-words\">Jika kamu memiliki passion di bidang keuangan, teliti, dan siap berkontribusi dalam pertumbuhan perusahaan, kami menunggumu! 📊</p><p class=\"font-claude-response-body whitespace-normal break-words\"><br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">Yang Kami Cari:</p><p class=\"font-claude-response-body whitespace-normal break-words\">✅ Min. S1 Akuntansi/Keuangan/Manajemen<br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">✅ Mahir Microsoft Excel<br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">✅ Teliti &amp; bertanggung jawab</p><p class=\"font-claude-response-body whitespace-normal break-words\"><br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">Ini saatnya untuk hashtag #RiseToServe bersama PMPLand!</p><p class=\"font-claude-response-body whitespace-normal break-words\"><br /></p><p class=\"font-claude-response-body whitespace-normal break-words\"><span style=\"font-size:0.875rem;\">📩 Lamar sekarang: <a href=\"http://bit.ly/LokerFinancePMPLand\">bit.ly/LokerFinancePMPLand</a></span></p><p class=\"font-claude-response-body whitespace-normal break-words\">📍 Penempatan: Cirebon, Jawa Barat</p><p class=\"font-claude-response-body whitespace-normal break-words\"><br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">📩 <a href=\"https://www.kitalulus.com/company/pmpland-fcvv?tab=PROFILE\">Lihat Karir PMPLand Lainnya!</a></p><p class=\"font-claude-response-body whitespace-normal break-words\"><br /></p><p class=\"font-claude-response-body whitespace-normal break-words\">#PMPLand #RiseToServe #Loker #LokerCirebon #LokerFinance #StaffKeuangan #LowonganKerja #KarirCirebon</p>', '2025-12-01 08:19:05', '2026-04-09 02:45:37', '2025-12-01 08:19:05', 2, 'Staff,Finance,PMPLand,Property,Loker,Lowongan Kerja, Head Office, Kerja', 'Lowongan Kerja Staff Finance di PMPLand', 'https://app.pmpland.co.id/file-download/sharing/c36e5dab9292e312a66040edd63aac37/596c73d51624694852c8597ae485017a/lokerfinancepmp.jpg', 'Ardhia Shafira Gianti', '+07:00'),
(24, 1, ' Job Vacancy: Finance Supervisor at Head Office PMPLand !', NULL, NULL, '<p>We Are Hiring! – *Finance Supervisor*</p><p><br /></p><p>PMPLand Group sedang mencari *Finance Supervisor* untuk bergabung bersama tim kami di Cirebon.</p><p><br /></p><p>Kami mencari kandidat yang memiliki pengalaman di bidang keuangan/akuntansi, kemampuan leadership yang baik, serta siap berkembang bersama perusahaan.</p><p><br /></p><p>Kualifikasi utama:</p><p><br /></p><p>- S1 Akuntansi/Keuangan/Manajemen</p><p>- Pengalaman 3–5 tahun di bidang terkait</p><p>- Pengalaman sebagai Supervisor/Team Leader</p><p>- Memahami cash flow &amp; treasury</p><p>- Pengalaman di industri properti menjadi nilai tambah</p><p><br /></p><p>📍 Penempatan: Cirebon, Jawa Barat</p><p><br /></p><p>Jika Anda siap untuk bertumbuh bersama kami, segera kirimkan lamaran Anda melalui QR yang tersedia.</p><p><br /></p><p>Let’s build something great together!</p><p><br /></p><p>#WeAreHiring #FinanceSupervisor #KarirCirebon #LowonganKerja #PMPLand #HiringNow</p>', '2026-04-13 05:07:34', NULL, '2026-04-13 12:07:34', 1, 'Finance,Supervisor,PMPLand,Loker,Property,Lowongan Kerja,Head Office,Cirebon', 'Lowongan Kerja Finance Supervisor di PMPLand Group', 'https://app.pmpland.co.id/thumb-260413120322--640x640-bgNoBG-0b839c5832296732dab35046e415d1e1-loker-finance-spv-PMPLand-Group.jpeg', 'Ardhia Shafira Gianti', '+07:00');
